import sys, json, subprocess, re
sys.path.insert(0, "/tmp/xt"); sys.path.insert(0, "/home/tirandagan.guest/naive-arm/output")
from xargs import xargs_syntax_spec
opts, pos = xargs_syntax_spec[0]
help_txt = subprocess.run(["xargs","--help"],capture_output=True,text=True).stdout
help_opts = set(re.findall(r"(?<![\w-])(--?[\w-]+)", help_txt.split("Please see")[0]))
help_opts = {o for o in help_opts if o.startswith("-") and not o.startswith("-blank")}
spec_opts = set()
for n in opts: spec_opts.update([n.flag]+n.alias)
print("in help but not spec:", sorted(help_opts-spec_opts))
print("in spec but not help:", sorted(spec_opts-help_opts))
# every spelling must be accepted by the binary; every Flag must NOT consume the next word
def run(args, inp="a b\n"):
    return subprocess.run(["xargs"]+args, input=inp, capture_output=True, text=True)
bad=[]
for n in opts:
    for sp in [n.flag]+n.alias:
        if sp in ("--help","--version","--show-limits","-o","--open-tty","-p","--interactive"): continue
        if n.kind=="Flag":
            r=run([sp,"echo","X"])
            if r.returncode or not r.stdout.startswith("X"): bad.append((sp,r.stderr.strip()))
        else:
            val={"Path":"/tmp/xin.txt","Delimiter":" ","Integer":"1","Variable":"V","String":"ZZ"}[n.kind]
            forms=[[sp+"="+val] if sp.startswith("--") else [sp+val]]
            if not n.eq: forms.append([sp,val])
            for f in forms:
                r=run(f+["echo","X"])
                if r.returncode or not r.stdout.startswith("X"): bad.append((f,r.stderr.strip()))
            # with value omitted: non-eq nodes must error, eq (optional) nodes must accept bare form
            r=run([sp,"echo","X"])
            if n.eq and (r.returncode or not r.stdout.startswith("X")): bad.append((sp,"bare optional failed",r.stderr.strip()))
            if not n.eq and r.returncode==0 and r.stdout.startswith("X"): bad.append((sp,"bare mandatory unexpectedly ok"))
print("spec/binary mismatches:", bad)
# Integer min/max checks
for n in opts:
    if n.kind=="Integer" and n.min is not None:
        r=run([n.flag,str(n.min-1),"echo"]); assert r.returncode!=0, (n, "min-1 accepted")
        r=run([n.flag,str(n.min),"echo","X"]); assert r.returncode==0 and n.flag!="-l", (n,"min rejected")
    if n.kind=="Integer" and n.max is not None:
        r=run([n.flag,str(n.max+1),"echo"]); assert r.returncode!=0, (n,"max+1 accepted")
print("integer bounds ok")
# JSON table consistency with syntax spec
tbl=json.load(open("/home/tirandagan.guest/naive-arm/output/annotation/xargs.json"))
jflags={s for e in tbl["flag"] for s in ([e] if isinstance(e,str) else e)}
jopts={s for e in tbl["option"] for s in e[:-1]}
print("json flags+options == spec spellings:", jflags|jopts==spec_opts, sorted(spec_opts-(jflags|jopts)))
