# simulate PaSh parser on sample invocations
def pash_parse(words):
    fo=[]; i=0
    while i<len(words):
        w=words[i]
        if w in jflags: fo.append((w,)); i+=1
        elif w in jopts: fo.append((w,words[i+1])); i+=2
        elif w.startswith("-") and len(w)>2 and not w.startswith("--") and all("-"+c in jflags for c in w[1:]): fo+= [("-"+c,) for c in w[1:]]; i+=1
        else: break
    return fo, words[i:]
for inv in [["-n","1","echo","-t"],["-0","-r","rm","-f"],["-a","f.txt","-I","{}","cp","{}","dst"],["-tr","echo"],["-d",":","--max-args","2","cat"],["cat"],[]]:
    print(inv,"->",pash_parse(inv))
